{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2862272177","pull_request_review_id":3864607096,"id":2862272177,"node_id":"PRRC_kwDOQ6DXvM6qms6x","diff_hunk":"@@ -0,0 +1,226 @@
+import { type Page, expect } from '@playwright/test';
+
+/**
+ * Navigate to the Settings page and click the Security tab.
+ *
+ * Waits for the security tab content to be visible before returning.
+ */
+export async function navigateToSecurityTab(page: Page): Promise<void> {
+  // Navigate to settings (hash router)
+  await page.evaluate(() => {
+    window.location.hash = '#/settings';
+  });
+  await page.waitForURL('**/settings', { timeout: 15_000 });
+
+  // Click the SECURITY tab
+  const securityTab = page.locator('#tab-security');
+  await securityTab.waitFor({ state: 'visible', timeout: 10_000 });
+  await securityTab.click();
+
+  // Wait for the security tab content to render
+  await page.locator('[data-testid="security-tab"]').waitFor({ state: 'visible', timeout: 10_000 });
+}
+
+/**
+ * Read the MFA status badge text from the Security tab.
+ *
+ * Assumes the Security tab is already visible. Returns the text
+ * content of the status badge (e.g. "[ENABLED]" or "[DISABLED]").
+ */
+export async function getMfaStatusText(page: Page): Promise<string> {
+  const badge = page.locator('[data-testid="mfa-status-badge"]');
+  await badge.waitFor({ state: 'visible', timeout: 10_000 });
+  const text = await badge.textContent();
+  return text?.trim() ?? '';
+}
+
+/**
+ * Run through the full MFA enrollment wizard.
+ *
+ * Assumes the page is on the Security tab with MFA currently disabled.
+ * Steps:
+ * 1. Click --enable-mfa button
+ * 2. Step 1: Click --continue
+ * 3. Step 2: Wait for enableMFA to complete (hits Devnet, ~10-15s)
+ * 4. Extract recovery phrase words
+ * 5. Check acknowledge checkbox
+ * 6. Click --continue
+ * 7. Step 3: Click --done
+ *
+ * Returns the 24-word recovery phrase as a single space-separated string.
+ *
+ * @param page - Page on the Security tab
+ * @param options.enableTimeout - Max time to wait for MFA enablement (default: 45s)
+ */
+export async function enrollMfa(
+  page: Page,
+  options: { enableTimeout?: number } = {}
+): Promise<string> {
+  const enableTimeout = options.enableTimeout ?? 45_000;
+
+  // Click the --enable-mfa button to open the wizard
+  const enableBtn = page.locator('[data-testid="mfa-enable-btn"]');
+  await enableBtn.waitFor({ state: 'visible', timeout: 10_000 });
+  await enableBtn.click();
+
+  // Step 1: Wizard explanation screen
+  await page
+    .locator('[data-testid="mfa-wizard-step-1"]')
+    .waitFor({ state: 'visible', timeout: 10_000 });
+  const continueBtn1 = page.locator('[data-testid="mfa-wizard-continue"]');
+  await continueBtn1.click();
+
+  // Step 2: Wait for MFA enablement + recovery phrase generation
+  await page
+    .locator('[data-testid="mfa-wizard-step-2"]')
+    .waitFor({ state: 'visible', timeout: 10_000 });
+
+  // Wait for loading to finish (enableMFA hits Devnet — can take 10-15s)
+  // Race between: recovery phrase grid (success) vs error div (failure)
+  const gridLocator = page.locator('[data-testid="recovery-phrase-grid"]');
+  const errorLocator = page.locator('[data-testid="mfa-wizard-error"]');
+
+  const outcome = await Promise.race([
+    gridLocator.waitFor({ state: 'visible', timeout: enableTimeout }).then(() => 'grid' as const),
+    errorLocator.waitFor({ state: 'visible', timeout: enableTimeout }).then(() => 'error' as const),
+  ]);
+
+  if (outcome === 'error') {
+    const errorText = await errorLocator.textContent();
+    throw new Error(`MFA enrollment failed: ${errorText}`);
+  }","path":"tests/e2e/utils/mfa-helpers.ts","commit_id":"4c88ac078c28e0b8cf4ac377c0cb545673eaa0dc","original_commit_id":"f5daa736a5b16d5bc5d03e3a50b6a0d8353afa51","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Good point — switched to `gridLocator.or(errorLocator).waitFor()` followed by `errorLocator.isVisible()` check. Cleaner and avoids the dangling promise rejection.","created_at":"2026-02-27T03:10:18Z","updated_at":"2026-02-27T03:10:18Z","html_url":"https://github.com/FSM1/cipher-box/pull/213#discussion_r2862272177","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/213","_links":{"self":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2862272177"},"html":{"href":"https://github.com/FSM1/cipher-box/pull/213#discussion_r2862272177"},"pull_request":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/213"}},"reactions":{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2862272177/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,"heart":0,"rocket":0,"eyes":0},"start_line":80,"original_start_line":80,"start_side":"RIGHT","line":91,"original_line":91,"side":"RIGHT","in_reply_to_id":2862253573,"author_association":"OWNER","original_position":91,"position":91,"subject_type":"line"}

